it('compiles a static tool schema once across multiple calls', async () => {
  const registry = new ToolRegistry();
  const def = {name: 'static', description: 'd', inputSchema: {type: 'object'}};
  registry.register(def, async () => 'ok');

  // Access private tools map to verify staticValidator reuse.
  const internal = registry as unknown as {tools: Map<string, {staticValidator: unknown}>};
  const originalValidator = internal.tools.get('static')?.staticValidator;
  expect(originalValidator).toBeDefined();

  for (let i = 0; i < 10; i++) {
    await registry.execute('static', {});
    expect(internal.tools.get('static')?.staticValidator).toBe(originalValidator);
  }
});

